fn is_prime(n: i8) -> bool {
    // By definition, primes are >= 2.
    if n < 2 {
        return false;
    }

    // Now n is in [2, 127]. Work in i16 to avoid any overflow issues.
    let n16 = n as i16;

    // Check divisors k with 2 <= k < n.
    let mut k: i16 = 2;
    while k < n16 {
        if n16 % k == 0 {
            return false;
        }
        k += 1;
    }

    true
}